<script setup lang="ts">
import {computed,onMounted,ref} from "vue";import type {EChartsOption} from "echarts";import {useSiteStore} from "@/stores/site";import {dataSourcesApi} from "@/api/dataSources";import PageHeader from "@/components/PageHeader.vue";import LoadingState from "@/components/LoadingState.vue";import ErrorState from "@/components/ErrorState.vue";import EmptyState from "@/components/EmptyState.vue";import StatusTag from "@/components/StatusTag.vue";import BaseChart from "@/components/BaseChart.vue";import type {AcquisitionOverview,DataSource,DataSourceDetail,ValidationLog} from "@/types";
const sites=useSiteStore(),rows=ref<DataSource[]>([]),details=ref<Record<number,DataSourceDetail>>({}),overview=ref<AcquisitionOverview|null>(null),loading=ref(true),error=ref<string|null>(null);const logs=computed(()=>Object.values(details.value).flatMap(x=>x.validation_logs).sort((a,b)=>b.created_at.localeCompare(a.created_at)));const pct=(v:number|null)=>v==null?"暂无数据":`${(v*100).toFixed(2)}%`;const fmt=(v:string|null|undefined)=>v?new Date(v).toLocaleString('zh-CN'):'暂无数据';const stageName=(v:string)=>({L1_SCHEMA:"L1 结构校验",L2_SEMANTIC:"L2 业务校验",L3_TEMPORAL:"L3 时序校验"} as Record<string,string>)[v]||v;
const siteName=(enterpriseId:number)=>sites.sites.find(x=>x.enterprise_id===enterpriseId)?.name||`企业 #${enterpriseId}`;
async function load(){loading.value=true;error.value=null;try{await sites.loadSites();[rows.value,overview.value]=await Promise.all([dataSourcesApi.list(),dataSourcesApi.overview()]);details.value=Object.fromEntries(await Promise.all(rows.value.map(async x=>[x.id,await dataSourcesApi.detail(x.id)] as const)))}catch(e){error.value=(e as {message?:string}).message||"数据质量加载失败"}finally{loading.value=false}}
const sourceOption=computed<EChartsOption>(()=>({tooltip:{},xAxis:{type:"category",data:rows.value.map(x=>x.name)},yAxis:{type:"value",max:100,name:"%"},series:[{type:"bar",name:"有效率",data:rows.value.map(x=>{const v=details.value[x.id]?.validation;return v?.total_records?Number((v.quality_rate*100).toFixed(2)):null})}]}));const stageOption=computed<EChartsOption>(()=>({tooltip:{},xAxis:{type:"category",data:["L1 结构","L2 业务","L3 时序"]},yAxis:{type:"value"},series:[{type:"bar",name:"拒绝",data:["L1_SCHEMA","L2_SEMANTIC","L3_TEMPORAL"].map(x=>overview.value?.validation[x]?.rejected??null)},{type:"bar",name:"警告",data:[null,null,overview.value?.validation.L3_TEMPORAL?.warnings??null]}]}));onMounted(load);
</script>
<template><section data-testid="system-data-quality-page"><PageHeader kicker="数据治理" title="数据质量管理" description="基于真实入库记录与 DataValidationLog 展示有效率、三级校验、异常和隔离数据。"><el-button @click="load">刷新质量</el-button></PageHeader><LoadingState v-if="loading"/><ErrorState v-else-if="error" :message="error" @retry="load"/><template v-else><div class="quality-kpis"><div><span>当前有效率</span><b>{{pct(overview?.quality_rate??null)}}</b></div><div><span>可用记录</span><b>{{Object.values(details).reduce((n,x)=>n+x.validation.valid_records,0)}}</b></div><div><span>隔离记录</span><b>{{overview?.quarantined??'暂无数据'}}</b></div><div><span>最近数据时间</span><b>{{overview?.latest_data_at?new Date(overview.latest_data_at).toLocaleString('zh-CN'):'暂无数据'}}</b></div></div><div class="chart-grid"><article class="panel"><h2>数据源质量</h2><BaseChart :option="sourceOption" :empty="!rows.length"/></article><article class="panel"><h2>分级校验</h2><BaseChart :option="stageOption" :empty="!logs.length"/><p class="note">现有日志只记录拒绝与警告，无法准确重建每一级通过数，因此不显示推测值。</p></article></div><article class="panel"><h2>三级校验规则</h2><el-descriptions :column="3" border><el-descriptions-item label="L1 结构校验">必填字段、设备类型、时间格式、数值类型</el-descriptions-item><el-descriptions-item label="L2 业务校验">单位合法性、单位标准化、物理数值范围</el-descriptions-item><el-descriptions-item label="L3 时序校验">重复时间戳、未来时间、可配置异常变化率</el-descriptions-item></el-descriptions></article><article class="panel"><h2>异常与隔离记录</h2><el-table :data="logs" empty-text="暂无异常或隔离记录"><el-table-column label="来源"><template #default="{row}">{{details[row.data_source_id]?.source.name||row.data_source_id}}</template></el-table-column><el-table-column prop="created_at" label="记录时间"/><el-table-column label="校验级别"><template #default="{row}">{{stageName(row.validation_stage)}}</template></el-table-column><el-table-column prop="device_external_id" label="设备/计量点"/><el-table-column prop="code" label="错误类型"/><el-table-column prop="message" label="原因" min-width="220"/><el-table-column label="处理"><template #default="{row}"><StatusTag :status="row.level==='ERROR'?'ERROR':'WARNING'"/> {{row.disposition}}</template></el-table-column></el-table><EmptyState v-if="!logs.length" title="暂无异常或隔离记录" description="未发生校验问题时不会生成演示记录"/></article><article class="panel"><h2>数据源质量明细</h2><el-table :data="rows" empty-text="暂无数据源"><el-table-column prop="name" label="数据源"/><el-table-column label="有效率"><template #default="{row}">{{details[row.id]?.validation.total_records?pct(details[row.id].validation.quality_rate):'暂无数据'}}</template></el-table-column><el-table-column label="有效 / 隔离 / 警告"><template #default="{row}">{{details[row.id]?.validation.valid_records??'--'}} / {{details[row.id]?.validation.quarantined_records??'--'}} / {{details[row.id]?.validation.warning_records??'--'}}</template></el-table-column><el-table-column label="最近数据"><template #default="{row}">{{details[row.id]?.status.last_received_at?new Date(details[row.id].status.last_received_at).toLocaleString('zh-CN'):'暂无数据'}}</template></el-table-column></el-table></article></template></section></template>
<style scoped>.quality-kpis{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin:14px 0}.quality-kpis>div{padding:16px;background:#fff;border:1px solid #dce7e3;border-radius:10px;display:flex;flex-direction:column;gap:8px}.quality-kpis b{font-size:22px}.chart-grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}.note{color:#71807a;font-size:13px}@media(max-width:900px){.quality-kpis,.chart-grid{grid-template-columns:1fr}}</style>
